mapper.select:
SELECT COUNT(1)
FROM STL_SEC_ACCT_INFO
WHERE SEC_ACCT_ID = #{finprodId}

SELECT distinct PSR.PORTFOLIO_ID portfolioId, PSR.SEC_ACCT_ID secAcctId, PSR.BRANCH branch, PSR.FINPROD_ID finprodId, PSR.INV_AIM invAim, PSR.RECE_AMT receAmt, PSR.PENALTY_INT_AMT penaltyIntAmt, FTP.BRANCH_TYPE branchType, PSR.CCY ccy FROM PTL_SEC_RECEIVABLES PSR LEFT JOIN FIN_TRADE_PRODUCT FTP ON PSR.FINPROD_ID = FTP.FINPROD_ID AND PSR.BRANCH = FTP.BRANCH WHERE 1=1
and PSR.FINPROD_ID = #{finprodId}
AND PSR.CDATE = #{cdate}
AND PSR.PORTFOLIO_ID = #{portfolioId}
AND PSR.SEC_ACCT_ID = #{secAcctId}
AND PSR.INV_AIM = #{invAim}

SELECT B.* FROM TRD_DEAL_TOTAL_ADD B left join TRD_FIN_PRODUCT_DEAL_TOTAL D on
D.TOTLE_TRADE_ID = B.TOTLE_TRADE_ID WHERE D.P_TOTLE_TRADE_ID = #{totleTradeId}
AND D.trade_status != '03'

SELECT B.* FROM TRD_PRODUCT_DEAL B left join TRD_FIN_PRODUCT_DEAL_TOTAL D on
D.TOTLE_TRADE_ID = B.TOTLE_TRADE_ID WHERE D.P_TOTLE_TRADE_ID = #{totleTradeId}
AND D.trade_status != '03'

SELECT SUM(AMOUNT) receAmt, PORTFOLIO_ID portfolioId, FINPROD_ID finprodId, BRANCH branch, SEC_ACCT_ID secAcctId, INV_AIM invAim, CCY ccy, PAY_DATE tradeDate, REC_TYPE recType FROM PTL_RECE_POSITION_FLOW WHERE HODING_TYPE = '03'
AND FINPROD_ID = #{finprodId}
AND CDATE <=#{cdate}
AND PORTFOLIO_ID = #{portfolioId}
AND INV_AIM = #{invAim}
AND SEC_ACCT_ID = #{secAcctId}
AND CCY = #{ccy}
AND BRANCH = #{branch}
GROUP BY PORTFOLIO_ID, FINPROD_ID, BRANCH, SEC_ACCT_ID, INV_AIM, CCY, PAY_DATE, REC_TYPE

SELECT SUM(AMOUNT) shareAmt, PORTFOLIO_ID portfolioId, FINPROD_ID finprodId, BRANCH branch, SEC_ACCT_ID secAcctId, INV_AIM invAim, HODING_TYPE hodingType, CCY ccy FROM ETR_SEC_POSITION_FLOW WHERE BRANCH = '0' AND (HODING_TYPE = '03' or HODING_TYPE = 'E01')
AND FINPROD_ID = #{finprodId}
AND CDATE <=#{cdate}
AND PORTFOLIO_ID = #{portfolioId}
AND INV_AIM = #{invAim}
AND SEC_ACCT_ID = #{secAcctId}
AND CCY = #{ccy}
GROUP BY PORTFOLIO_ID , FINPROD_ID , BRANCH , SEC_ACCT_ID , INV_AIM , HODING_TYPE, CCY

SELECT SUM(AMOUNT) shareAmt, PORTFOLIO_ID portfolioId, FINPROD_ID finprodId, BRANCH branch, SEC_ACCT_ID secAcctId, INV_AIM invAim, CCY ccy FROM PTL_SEC_POSITION_FLOW WHERE BRANCH = '0' AND (HODING_TYPE = '03' or HODING_TYPE = 'E01')
AND FINPROD_ID = #{finprodId}
AND CDATE <=#{cdate}
AND PORTFOLIO_ID = #{portfolioId}
AND INV_AIM = #{invAim}
AND SEC_ACCT_ID = #{secAcctId}
AND CCY = #{ccy}
GROUP BY PORTFOLIO_ID, FINPROD_ID, BRANCH, SEC_ACCT_ID, INV_AIM, CCY
